<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="app"></div>
  <script>
    const faqItems = [
      {
        question: "Why do cats purr?",
        answer: "Cats often purr when they feel content, but they may also purr to self-soothe when stressed, tired, or recovering. The sound comes from rapid muscle movements around the larynx while they breathe."
      },
      {
        question: "How much sleep do cats need?",
        answer: "Most cats sleep between 12 and 16 hours a day, and some nap even longer. Their sleep pattern comes from their instinct as crepuscular hunters that conserve energy between active periods."
